mapper.select:
SELECT distinct a.id, a.`code`, a.type, a.`status`, a.source_warehouse, a.target_warehouse, a.create_name, a.create_time, a.update_time, a.affirm_name, a.affirm_time, note FROM wms_transfer_slip a LEFT JOIN wms_transfer_slip_info b ON b.transfer_slip_id = a.id
a.del_flag = 0
and a.code LIKE CONCAT('%',#{dto.code},'%')
and b.material_name LIKE CONCAT('%',#{dto.materialName},'%')
and b.material_code LIKE CONCAT('%',#{dto.materialCode},'%')
AND a.status = #{dto.status}
and a.type = #{dto.type}
and a.source_warehouse = #{dto.sourceWarehouse}
and a.target_warehouse = #{dto.targetWarehouse}
and b.source_shelf_name LIKE CONCAT('%',#{dto.sourceShelfName},'%')
and b.source_shelf_code LIKE CONCAT('%',#{dto.sourceShelfCode},'%')
and b.target_shelf_name LIKE CONCAT('%',#{dto.targetShelfName},'%')
and b.target_shelf_code LIKE CONCAT('%',#{dto.targetShelfCode},'%')
and b.batch LIKE CONCAT('%',#{dto.batch},'%')
and b.case_no LIKE CONCAT('%',#{dto.caseNo},'%')
and a.create_name LIKE CONCAT('%',#{dto.createName},'%')
and a.affirm_name LIKE CONCAT('%',#{dto.affirmName},'%')
and a.create_time BETWEEN #{dto.createStartTime} and #{dto.createEndTime}
and a.affirm_time BETWEEN #{dto.affirmStartTime} and #{dto.affirmEndTime}
ORDER BY a.update_time DESC

select info.material_id, sum(quantity) as quantity  from wms_transfer_slip wts join wms_transfer_slip_info info on wts.id = info.transfer_slip_id and info.del_flag = 0
where wts.del_flag = 0

    and (wts.source_warehouse in

        #{id}

    or wts.target_warehouse in

        #{id}
    )


    and wts.affirm_time between #{startTime} and #{endTime}

and wts.`status` in(1,2,3)
group by info.material_id;

SELECT wtsi.material_name, sum(wtsi.quantity) quantity FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wts.source_warehouse = #{id} and wts.create_time between #{startTime} and #{endTime} and wtsi.material_name in
#{name}
GROUP BY wtsi.material_name

SELECT wtsi.material_id, wtsi.unit, wts.create_time, sum(wtsi.quantity) quantity FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
GROUP BY wtsi.unit, wts.create_time, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y-%m-%d' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y-%m' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id

SELECT DATE_FORMAT( wts.create_time, '%Y' ) field1, wtsi.material_id field2, sum( wtsi.quantity ) field3, wtsi.unit field4 FROM wms_transfer_slip_info wtsi LEFT JOIN wms_transfer_slip wts ON wts.id = wtsi.transfer_slip_id WHERE wts.del_flag = 0 and wtsi.target_shelf in
#{warehouseId}
and wtsi.material_id in
#{materialId}
and wts.create_time BETWEEN #{start} and #{end} GROUP BY wtsi.unit, field1, wtsi.material_id

SELECT COUNT( a.id ) FROM wms_transfer_slip a JOIN wms_transfer_slip_info b ON a.id = b.transfer_slip_id WHERE a.del_flag = 0 AND b.del_flag = 0 AND a.`status` = 0 AND ( b.source_shelf IN
#{shelfId}
or b.target_shelf in
#{shelfId}
)

SELECT b.material_id, sum( b.quantity ) quantity FROM wms_transfer_slip a JOIN wms_transfer_slip_info b ON a.id = b.transfer_slip_id WHERE a.del_flag = 0 AND b.del_flag = 0
and a.target_warehouse = #{warehouseId}
and a.affirm_time between #{startTime} and #{endTime}
and b.material_id in
#{id}
GROUP BY b.material_id;

SELECT b.material_id, sum( b.quantity ) quantity FROM wms_transfer_slip a JOIN wms_transfer_slip_info b ON a.id = b.transfer_slip_id WHERE a.del_flag = 0 AND b.del_flag = 0
and a.source_warehouse = #{warehouseId}
and a.affirm_time between #{startTime} and #{endTime}
and b.material_id in
#{id}
GROUP BY b.material_id;

SELECT b.material_id, COUNT(DISTINCT a.id) AS count FROM wms_transfer_slip a JOIN wms_transfer_slip_info b ON a.id = b.transfer_slip_id WHERE a.del_flag = 0 AND b.del_flag = 0
and a.source_warehouse = #{warehouseId}
and a.affirm_time between #{startTime} and #{endTime}
and b.material_id in
#{id}
GROUP BY b.material_id;

SELECT b.material_id, COUNT(DISTINCT a.id) AS count FROM wms_transfer_slip a JOIN wms_transfer_slip_info b ON a.id = b.transfer_slip_id WHERE a.del_flag = 0 AND b.del_flag = 0
and a.target_warehouse = #{warehouseId}
and a.affirm_time between #{startTime} and #{endTime}
and b.material_id in
#{id}
GROUP BY b.material_id;

select warehouse_id as warehouseId, target_shelf_name as targetShelfName, any_value(target_shelf_id) as targetShelfId, any_value(material_id) as materialId, material_name as materialName, type, status, classes, COUNT(*) as caseNum, sum(quantity) as totalQuantity, group_concat(case_no ORDER BY case_no SEPARATOR ', ') as caseNo from ( select c.warehouse_id as warehouse_id, a.target_shelf_name as target_shelf_name, a.target_shelf as target_shelf_id, a.material_name as material_name, a.material_id as material_id, b.type as type, CASE WHEN b.status = 0 THEN '已创建' WHEN b.status = 1 THEN '已确认' WHEN b.status = 2 THEN '已同步' WHEN b.status = 5 THEN '已冲销' END AS status, CASE WHEN TIME(b.create_time) BETWEEN '20:00:00' AND '23:59:59' OR TIME(b.create_time) BETWEEN '00:00:00' AND '08:00:00' THEN '夜班' WHEN TIME(b.create_time) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' END AS classes, a.case_no as case_no, a.quantity as quantity from wms_transfer_slip_info a join wms_transfer_slip b on a.transfer_slip_id = b.id join wms_inventory c on c.id = a.source_inventory_id where a.del_flag = 0 AND b.del_flag = 0
AND b.create_time >= #{dto.startTime} AND b.create_time < #{dto.endTime}
) as newList GROUP BY warehouseId, targetShelfName, materialName, type, status, classes ORDER BY target_shelf_name, classes

select c.warehouse_id as warehouseId, c.warehouse_name as warehouseName, a.target_shelf_name as targetShelfName, a.target_shelf as targetShelfId, a.material_name as materialName, a.material_id as materialId, b.type as type, b.status, b.affirm_name AS affirm_name, b.affirm_time AS affirm_time, b.create_name AS create_name, b.create_time AS create_time, CASE WHEN TIME(b.create_time) BETWEEN '20:00:00' AND '23:59:59' OR TIME(b.create_time) BETWEEN '00:00:00' AND '08:00:00' THEN '夜班' WHEN TIME(b.create_time) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' END AS classes, a.case_no as case_no, a.quantity as quantity from wms_transfer_slip_info a join wms_transfer_slip b on a.transfer_slip_id = b.id join wms_inventory c on c.id = a.source_inventory_id where a.del_flag = 0 AND b.del_flag = 0
and c.case_no in
#{caseNo}
